// 1. Daten aus der Query holen
// Wir gehen davon aus, dass DeinQuery so konfiguriert ist, dass er 
// die 5 aktuellsten Dokumente sortiert nach savedAt liefert.
const rawData = {{ FindReports.data }} || [];

// 2. Umkehren, damit das älteste Dokument der 5 links steht
const recentDocs = [...rawData].reverse();

// 3. Achsen-Daten vorbereiten
const categories = recentDocs.map(doc => doc.finsihed || 'Test');

// 4. Serien-Daten vorbereiten
const correctData = recentDocs.map(doc => doc.correct);
const incorrectData = recentDocs.map(doc => doc.incorrect);

// 5. ECharts Konfiguration
return {
  tooltip: {
    trigger: 'axis',
    axisPointer: {
      type: 'shadow'
    }
  },
  legend: {
    data: ['Korrekt', 'Inkorrekt'],
    bottom: 0
  },
  grid: {
    top: 30,
    bottom: 50,
    left: 40,
    right: 20,
    containLabel: true
  },
  xAxis: {
    type: 'category',
    data: categories,
    axisLabel: {
      interval: 0,
      rotate: 15,
      fontSize: 10
    }
  },
  yAxis: {
    type: 'value',
    name: 'Anzahl Fragen'
  },
  series: [
    {
      name: 'Korrekt',
      type: 'bar',
      stack: 'total',
      data: correctData,
      itemStyle: {
        color: '#22c55e' // Grün
      },
      label: {
        show: true,
        position: 'inside'
      }
    },
    {
      name: 'Inkorrekt',
      type: 'bar',
      stack: 'total',
      data: incorrectData,
      itemStyle: {
        color: '#ef4444' // Rot
      },
      label: {
        show: true,
        position: 'inside'
      }
    }
  ]
};
